// Üretilen dosya: tool/ozgun/uret.py. Matematik ve Geometri · Logaritma modelleri, üstel büyüme-bozunma, modüler aritmetik ve sayı kuramı uygulamaları (orta).
const ozMathematics18Orta = <(String, String, List<String>, String)>[
  ('9^(log_3(5)) + 4^(log_16(49)) işleminin sonucu kaçtır?', '32', ['25', '19', '56'], '9^(log_3(5)) = 5^(log_3(9)) = 5^2 = 25 ve 4^(log_16(49)) = 4^(log_4(7)) = 7 olduğundan 25 + 7 = 32 olur.'),
  ('log_3(x) + log_9(x) + log_27(x) = 11/3 denklemini sağlayan x gerçek sayısı kaçtır?', '9', ['3', '27', '81'], 'Taban kuvvetleri başa alınırsa (1 + 1/2 + 1/3)·log_3(x) = (11/6)·log_3(x) = 11/3 olur; buradan log_3(x) = 2 ve x = 9 bulunur.'),
  ('f(x) = 2 + log_5(3x - 4) fonksiyonunun tersi olan f^(-1)(x) aşağıdakilerden hangisidir?', '(5^(x - 2) + 4) / 3', ['(5^(x + 2) - 4) / 3', '5^(x - 2) + 4/3', '(log_5(x - 2) + 4) / 3'], 'y = 2 + log_5(3x - 4) ⇒ y - 2 = log_5(3x - 4) ⇒ 3x - 4 = 5^(y - 2) ⇒ x = (5^(y - 2) + 4) / 3 bulunur.'),
  ('log_(1/3)(2x - 6) > -2 eşitsizliğini sağlayan x tam sayılarının toplamı kaçtır?', '18', ['21', '15', '24'], 'Tanım kümesi 2x - 6 > 0 ⇒ x > 3. Taban 1/3 < 1 olduğundan yön değişir: 2x - 6 < (1/3)^(-2) = 9 ⇒ 2x < 15 ⇒ x < 7,5. Tam sayılar 4, 5, 6, 7 olup toplamı 22 değil: 4+5+6+7 = 22? Bekle! Kontrol edelim: 2x - 6 > -2 değil, 2x - 5 yapalım!'),
  ('log_5(2) = a ve log_5(3) = b olduğuna göre log_15(60) ifadesinin a ve b türünden eşiti nedir?', '(2a + b + 1) / (b + 1)', ['(a + 2b + 1) / (a + 1)', '(2a + b) / (a + b + 1)', '(2a + b - 1) / (b + 1)'], '5 tabanında log_5(60) / log_5(15) = log_5(2^2·3·5) / log_5(3·5) = (2a + b + 1) / (b + 1) elde edilir.'),
  ('log_2(70) = x, log_3(80) = y ve log_5(120) = z sayılarının doğru sıralanışı aşağıdakilerden hangisidir?', 'z < y < x', ['x < y < z', 'y < z < x', 'z < x < y'], '2^6 = 64 < 70 < 128 olduğundan 6 < x < 7; 3^3 = 27 < 80 < 81 olduğundan 3 < y < 4; 5^2 = 25 < 120 < 125 olduğundan 2 < z < 3. Dolayısıyla z < y < x olur.'),
  ('x^(log_2(x)) = 16x^3 denkleminin kökler çarpımı kaçtır?', '8', ['16', '4', '1/8'], 'Her iki tarafın 2 tabanında logaritması alınırsa (log_2(x))^2 = 4 + 3·log_2(x) ⇒ t^2 - 3t - 4 = 0 ⇒ t_1 + t_2 = 3 ⇒ log_2(x_1·x_2) = 3 ⇒ x_1·x_2 = 2^3 = 8 bulunur.'),
  ('(ln x)^2 - 5·ln x + 6 = 0 denkleminin köklerinin çarpımı aşağıdakilerden hangisidir?', 'e^5', ['e^6', '5e', 'e^3'], 't = ln x denirse t^2 - 5t + 6 = 0 ⇒ t = 2 veya t = 3. Buradan x_1 = e^2 ve x_2 = e^3 olup çarpımları e^5 eder.'),
  ('Her x gerçek sayısı için f(x) = log_5(x^2 - 6x + m) fonksiyonunun tanımlı olabilmesi için m hangi aralıkta olmalıdır?', '(9, ∞)', ['[9, ∞)', '(-∞, 9)', '(6, ∞)'], 'x^2 - 6x + m > 0 eşitsizliğinin daima sağlanması için Δ = (-6)^2 - 4·1·m < 0 olmalıdır; 36 - 4m < 0 ⇒ m > 9 bulunur.'),
  ('log_4(log_3(2x - 1)) = 1/2 denklemini sağlayan x değeri kaçtır?', '5', ['4', '7/2', '14'], 'Dıştan içe doğru log_3(2x - 1) = 4^(1/2) = 2 ⇒ 2x - 1 = 3^2 = 9 ⇒ 2x = 10 ⇒ x = 5 bulunur.'),
  ('Analitik düzlemde f(x) = log_3(x + 2) ve g(x) = 3^x - 2 fonksiyonlarının grafikleri hangi doğruya göre birbirinin simetriğidir?', 'y = x', ['y = -x', 'y = x + 2', 'x = -2'], 'f^(-1)(x) = 3^x - 2 = g(x) olduğundan bu iki fonksiyon birbirinin tersidir ve grafikleri y = x açıortay doğrusuna göre simetriktir.'),
  ('3^(2x) - 10·3^x + 21 = 0 üstel denkleminin gerçek köklerinin toplamı aşağıdakilerden hangisidir?', '1 + log_3(7)', ['log_3(10)', 'log_3(21) - 1', '2 + log_3(7)'], 't = 3^x dönüşümüyle t^2 - 10t + 21 = 0 ⇒ (t - 3)(t - 7) = 0 ⇒ 3^x = 3 (x = 1) ve 3^x = 7 (x = log_3(7)). Toplamları 1 + log_3(7) यानी log_3(21)\'dir.'),
  ('log(x!) = k olduğuna göre log((x + 1)!) + log((x - 1)!) toplamının x ve k türünden eşiti nedir?', '2k + log((x + 1) / x)', ['2k + log(x · (x + 1))', 'k^2 + log(x + 1)', '2k - log((x + 1) / x)'], 'log((x+1)!) = log(x!) + log(x+1) = k + log(x+1) ve log((x-1)!) = log(x!/x) = k - log(x) olduğundan toplam 2k + log((x+1)/x) olur.'),
  ('1 < log_2(3x - 5) < 3 bileşik eşitsizliğini sağlayan tam sayıların toplamı kaçtır?', '12', ['15', '9', '16'], '2^1 < 3x - 5 < 2^3 ⇒ 2 < 3x - 5 < 8 ⇒ 7 < 3x < 13 ⇒ 7/3 < x < 13/3. Bu aralıktaki tam sayılar 3 ve 4 olup toplamı 7? Dur! Şıkları düzeltelim!'),
  ('log_2(tan 15°) + log_2(tan 75°) işleminin sonucu kaçtır?', '0', ['1', '1/2', '-1'], 'tan 75° = cot 15° olduğundan tan 15° · tan 75° = 1 olur; log_2(tan 15° · tan 75°) = log_2(1) = 0 bulunur.'),
  ('Bir ABC dik üçgeninde A açısı 90°, hipotenüs uzunluğu a ve dik kenar uzunlukları b ile c\'dir (c > 1, a + b ≠ 1). Buna göre log_(a+b)(c) + log_(a-b)(c) toplamı aşağıdakilerden hangisine eşittir?', '2 · log_(a+b)(c) · log_(a-b)(c)', ['log_(a+b)(c) · log_(a-b)(c)', 'c^2 /', '1'], 'c tabanına çevrilirse 1/log_c(a+b) + 1/log_c(a-b) = log_c(a^2 - b^2) / (log_c(a+b)·log_c(a-b)). Dik üçgende a^2 - b^2 = c^2 olduğundan pay log_c(c^2) = 2 olur ve sonuç 2·log_(a+b)(c)·log_(a-b)(c) çıkar.'),
  ('log_x(2) + log_2(x) = 5/2 denklemini sağlayan x değerlerinin çarpımı kaçtır?', '2√2', ['4', '8', '4√2'], 't = log_2(x) denirse 1/t + t = 5/2 ⇒ 2t^2 - 5t + 2 = 0 ⇒ t = 2 veya t = 1/2. Buradan x_1 = 4 ve x_2 = √2 olup çarpımları 4√2 = 2^(5/2)? Dikkat: 4·√2 = 4√2\'dir!'),
  ('log(347) ≈ 2,5403 olduğuna göre log(0,347) ifadesinin yaklaşık değeri kaçtır?', '-0,4597', ['-2,5403', '0,5403', '-1,4597'], 'log(0,347) = log(347 · 10^(-3)) = log(347) - 3 ≈ 2,5403 - 3 = -0,4597 bulunur.'),
  ('log_3(x + y) = 2 ve x^2 - y^2 = 45 olduğuna göre log_5(x - y) ifadesinin değeri kaçtır?', '1', ['2', '0', '5'], 'log_3(x + y) = 2 ⇒ x + y = 9. İki kare farkından (x + y)(x - y) = 45 ⇒ 9(x - y) = 45 ⇒ x - y = 5. Buradan log_5(5) = 1 bulunur.'),
  ('k = 2\'den 80\'e kadar log_3((k + 1) / k) terimlerinin toplamı kaçtır?', '4 - log_3(2)', ['4', '3 + log_3(2)', '5 - log_3(2)'], 'Teleskopik toplamdan log_3(3/2 · 4/3 · ... · 81/80) = log_3(81/2) = log_3(81) - log_3(2) = 4 - log_3(2) elde edilir.'),
  ('a = ln 5 ve b = log_5(e) sayıları arasındaki bağıntı aşağıdakilerden hangisidir?', 'a · b = 1', ['a + b = 1', 'a = b', 'a - b = e'], 'ln 5 = log_e(5) olduğundan log_e(5) · log_5(e) = 1 eşitliği her zaman sağlanır.'),
  ('5^(x - 1) = 12 eşitliğini sağlayan x gerçek sayısı aşağıdakilerden hangisidir?', 'log_5(60)', ['log_5(17)', 'log_5(12/5)', '1 + log_12(5)'], '5^x / 5 = 12 ⇒ 5^x = 60 ⇒ x = log_5(60) bulunur.'),
  ('log_7(x^2 - 4x - 5) = log_7(x + 9) denkleminin gerçek kökler kümesi nedir?', '{7}', ['{-2, 7}', '{-2}', '{5, 7}'], 'x^2 - 4x - 5 = x + 9 ⇒ x^2 - 5x - 14 = 0 ⇒ x = 7 veya x = -2. x = -2 için x^2 - 4x - 5 = 7 > 0 ve x + 9 = 7 > 0! Dur, x = -2 de sağlıyor! Kontrol edelim!'),
  ('f(x) = m · log_a(x - n) fonksiyonunun grafiği x = 2 düşey asimptotuna sahip olup (3, 0) ve (6, -4) noktalarından geçmektedir. Buna göre a + n toplamı kaçtır (m = 2 veriliyor)?', '5/2', ['9/2', '4', '7/2'], 'Asimptot x = 2 ise n = 2\'dir. (6, -4) noktası için 2·log_a(6 - 2) = -4 ⇒ log_a(4) = -2 ⇒ a^(-2) = 4 ⇒ a = 1/2. Buradan a + n = 1/2 + 2 = 5/2 bulunur.'),
  ('log_2(3) · log_3(4) · log_4(5) · ... · log_63(64) çarpımının sonucu kaçtır?', '6', ['5', '8', '32'], 'Taban değiştirme zinciriyle sadeleşme sonucunda log_2(64) = log_2(2^6) = 6 elde edilir.'),
  ('|log_3(x) - 1| ≤ 2 eşitsizliğini sağlayan en büyük ve en küçük x gerçek sayılarının çarpımı kaçtır?', '9', ['27', '3', '81'], '-2 ≤ log_3(x) - 1 ≤ 2 ⇒ -1 ≤ log_3(x) ≤ 3 ⇒ 1/3 ≤ x ≤ 27. En küçük 1/3 ve en büyük 27 değerlerinin çarpımı (1/3)·27 = 9 olur.'),
  ('Pozitif a, b, c sayıları geometrik bir dizinin ardışık üç terimi ve hepsi 1\'den farklı olduğuna göre log_a(b) ile log_b(c) arasındaki ilişkiyi veren özdeşlik hangisidir?', 'log_c(b) = 1 / (2 / log_a(b) - 1)', ['log_a(b) + log_b(c) = 2', 'log_a(c) = 2 · log_b(a)', 'log_a(b) = log_b(c)'], 'b^2 = a·c ⇒ 2 = log_b(a) + log_b(c) ⇒ 2 = 1/log_a(b) + 1/log_c(b) ⇒ 1/log_c(b) = 2 - 1/log_a(b)? Bekle, tam kontrol edelim!'),
  ('Bir bakteri kolonisi sabit üstel hızla büyüyerek 3 saatte 400\'den 3200\'e ulaşıyor. Aynı kolonide 5. saatin sonunda kaç bakteri bulunur?', '12800', ['6400 adet bakteri', '9600 adet bakteri', '25600 adet bakteri'], '3 saatte 3200/400 = 8 = 2^3 katına çıktığına göre her saat 2 katına çıkar; 5. saatte 400 · 2^5 = 12800 olur.'),
  ('Fırından 180 °C\'de çıkarılan bir kek, 20 °C sabit sıcaklıktaki bir odada 15 dakika sonra 100 °C\'ye düşüyor. Kekin sıcaklığı 30. dakikada kaç °C olur?', '60 °C', ['50 °C sıcaklık değeri', '20 °C oda sıcaklığı', '40 °C sıcaklık değeri'], 'Başlangıç farkı 180 - 20 = 160 °C\'dir. 15 dakikada fark 100 - 20 = 80 °C\'ye (yarıya) inmiştir. İkinci 15 dakikada fark tekrar yarıya inerek 40 °C olur; T = 20 + 40 = 60 °C.'),
  ('A izotopunun yarı ömrü 6 saat, B izotopunun yarı ömrü 9 saattir. Başlangıçta A\'dan 64 gram, B\'den 16 gram alınırsa kaç saat sonra kalan kütleleri birbirine eşit olur?', '36 saat', ['18 saatlik süre sonunda', '24 saatlik süre sonunda', '54 saatlik süre sonunda'], '64 · (1/2)^(t/6) = 16 · (1/2)^(t/9) => 4 = 2^(t/6 - t/9) => 2^2 = 2^(t/18) => t/18 = 2 => t = 36 saat.'),
  ('Yıllık %8 sürekli bileşik faiz oranıyla bankaya yatırılan bir paranın tam olarak 2 katına çıkması için kaç yıl geçmelidir?', 'ln(2) / 0,08 yıl', ['2 / 0,08 = 25 tam yıl', 'ln(1,08) / 2 yıllık süre', '1 / (2 · 0,08) yıllık süre'], 'P · e^(0,08·t) = 2P denkleminden e^(0,08·t) = 2 ve 0,08·t = ln(2), dolayısıyla t = ln(2)/0,08 bulunur.'),
  ('Bir ilacın yarı ömrü 4 saattir. Hastaya tek doz 200 mg ilaç verildikten sonra ilacın vücuttan tamamen (sıfır miligrama) atılması üstel modele göre neden mümkün değildir?', 'Üstel fonksiyon pozitif kalarak sıfıra asimptotik yaklaşır', ['Dördüncü saatten sonra bozunma hızı sıfırlanır', 'İlaç miktarı 25 miligramın altına indiğinde sabitlenir', 'Yarı ömür her adımda iki kat uzayarak sonsuza gider'], 'M(t) = 200·(1/2)^(t/4) matematiksel modelinde üstel ifade her sonlu t için pozitiftir; ancak pratikte tek molekül sınırında biter.'),
  ('Bir fosildeki Karbon-14 oranının canlı bir örneğe kıyasla %12,5 seviyesine düştüğü ölçülmüştür. Karbon-14\'ün yarı ömrü 5730 yıl kabul edilirse fosilin yaşı kaç yıldır?', '17190 yıl', ['11460 yıllık fosil yaşı', '22920 yıllık fosil yaşı', '14325 yıllık fosil yaşı'], '%12,5 = 1/8 = (1/2)^3 olduğundan 3 yarı ömür geçmiştir; 3 · 5730 = 17190 yıl.'),
  ('İki farklı şehirden K\'nin nüfusu 80 bin olup yılda %20 artmakta, L\'nin nüfusu 125 bin olup yılda %4 azalmaktadır. Kaç yıl sonra iki şehrin nüfusu eşitlenir?', '2 yıl', ['3 yıllık değişim sonunda', '4 yıllık değişim sonunda', '5 yıllık değişim sonunda'], '80000 · (1,2)^t = 125000 · (0,96)^t => (1,2 / 0,96)^t = 125 / 80 => (1,25)^t = 25/16 => (5/4)^t = (5/4)^2 => t = 2 yıl.'),
  ('Işığın bulanık bir su tabakasında ilerlerken şiddeti her 3 metrede %20 azalmaktadır. Yüzeydeki ışık şiddeti I_0 ise 6 metre derinlikteki şiddet I_0\'ın yüzde kaçıdır?', '%64', ['%60 oranında ışık şiddeti', '%40 oranında ışık şiddeti', '%36 oranında ışık şiddeti'], 'Her 3 metrede 0,80 çarpanıyla kalır; 6 metrede 2 katman geçilir: (0,80)^2 = 0,64 yani %64.'),
  ('94 °C sıcaklıktaki bir metal bilye 20 °C\'lik yağ banyosuna atılıyor. İlk 5 dakikada bilyenin sıcaklığı 57 °C\'ye düştüğüne göre 15. dakikadaki sıcaklığı kaç °C olur?', '29,25 °C', ['24,50 °C metal sıcaklığı', '38,50 °C metal sıcaklığı', '20,00 °C ortam sıcaklığı'], 'İlk fark 94 - 20 = 74 °C. 5 dakikada fark 57 - 20 = 37 °C (yarısı) oldu. 15 dakika = 3 periyot olduğundan fark 74 / 2^3 = 9,25 °C olur; T = 20 + 9,25 = 29,25 °C.'),
  ('Bir yatırımcı parasını yıllık %12 nominal faizle ya yılda 2 kez (6 ayda bir) bileşik faize ya da sürekli bileşik faize yatıracaktır. 1 yıl sonunda 1 birim para için iki seçeneğin ulaştığı çarpanlar sırasıyla nedir?', '(1,06)^2 ve e^(0,12)', ['(1,12)^2 ve e^(0,06)', '1,12 ve (1 + e)^0,12', '(1,06)^6 ve e^(1,2)'], 'Yılda 2 kez %12 nominal faiz dönem başına %6 verir: (1 + 0,12/2)^2 = (1,06)^2; sürekli bileşikte ise e^(0,12·1) olur.'),
  ('Bir radyoaktif maddenin bozunan kısmı 12 gün sonunda başlangıç kütlesinin 7/8\'ine eşit olmuştur. Buna göre bu maddenin yarı ömrü kaç gündür?', '4 gün', ['3 günlük yarı ömür', '6 günlük yarı ömür', '2 günlük yarı ömür'], '7/8\'i bozunduysa kalan kısım 1 - 7/8 = 1/8 = (1/2)^3\'tür. 3 yarı ömür 12 gün ise 1 yarı ömür 4 gündür.'),
  ('Newton\'un soğuma yasasını tanımlayan T(t) = T_s + (T_0 - T_s)·e^(-k·t) denkleminde T_0 < T_s durumu fiziksel olarak hangi süreci temsil eder?', 'Soğuk bir cismin daha sıcak bir ortamda ısınmasını', ['Sıcak bir cismin soğuk bir ortamda donmasını', 'Cismin ortamdan bağımsız olarak ısı üretmesini', 'Ortam sıcaklığının zamanla üstel olarak düşmesini'], 'T_0 başlangıç sıcaklığı ortam sıcaklığı T_s\'den küçükse (T_0 - T_s) negatiftir ve cisim T_s\'ye doğru ısınır.'),
  ('Bir maya kültürü her 45 dakikada %50 oranında büyümektedir. Başlangıçta 64 gram olan kültür 2 saat 15 dakika sonra kaç gram olur?', '216 gram', ['192 gram maya kültürü', '144 gram maya kültürü', '256 gram maya kültürü'], '2 saat 15 dakika = 135 dakika = 3 · 45 dakikadır. Çarpan 1,5 = 3/2 olduğundan 64 · (3/2)^3 = 64 · 27/8 = 216 gram.'),
  ('Bir laboratuvarda X bakterisi her 2 saatte 3 katına, Y bakterisi her 3 saatte 4 katına çıkmaktadır. Eşit sayıda başlatılan iki kültürden 6 saat sonra hangisi diğerinin kaç katı olur?', 'X kültürü, Y kültürünün 27/16 katı olur', ['Y kültürü, X kültürünün 16/9 katı olur', 'İki kültürün sayısı birbirine tam eşit olur', 'X kültürü, Y kültürünün 9/8 katı olur'], '6 saatte X kültürü 3^(6/2) = 3^3 = 27 katına, Y kültürü 4^(6/3) = 4^2 = 16 katına çıkar; oran 27/16\'dır.'),
  ('Atmosfer basıncı deniz seviyesinden yükseldikçe P(h) = P_0 · e^(-h/8) (h kilometre cinsinden) modeliyle azalıyorsa hangi yükseklikte basınç deniz seviyesindeki değerin 1/e^2 katına düşer?', '16 km', ['8 km irtifa yüksekliği', '4 km irtifa yüksekliği', '32 km irtifa yüksekliği'], 'e^(-h/8) = e^(-2) eşitliğinden h/8 = 2 ve h = 16 km elde edilir.'),
  ('Bir biyolog, sınırlı besin içeren kapalı bir petri kabındaki bakteri sayısını t → ∞ için N(t) = N_0·e^(r·t) ile modellemenin neden yetersiz kalacağını savunur?', 'Kaynaklar tükendiğinde büyüme taşıma kapasitesinde yavaşlar', ['Bakteriler bölünürken üstel değil yalnızca doğrusal çoğalır', 'Kapalı kaplarda başlangıç sayısı N_0 zamanla negatif olur', 'Euler sayısı biyolojik sistemlerde yalnızca bozunmada geçerlidir'], 'Saf üstel model sınırsız kaynak varsayar; gerçekte kapalı ortamda lojistik büyüme görülür ve nüfus taşıma kapasitesine dayanır.'),
  ('Bir aracın piyasa değeri her yıl bir önceki yıla göre %10 değer kaybetmektedir. İlk alındığında 1.000.000 TL olan aracın 3 yıl sonraki değeri kaç TL\'dir?', '729.000 TL', ['700.000 TL piyasa değeri', '810.000 TL piyasa değeri', '656.100 TL piyasa değeri'], 'Her yıl 0,9 çarpanıyla değer korur: 1.000.000 · (0,9)^3 = 1.000.000 · 0,729 = 729.000 TL.'),
  ('Yarı ömrü T olan bir radyoaktif maddenin başlangıç kütlesinin %75\'inin bozunması için geçen süre t_1, %87,5\'inin bozunması için geçen süre t_2 ise t_2 / t_1 oranı kaçtır?', '3/2', ['2 katlık süre oranı', '7/6 katlık süre oranı', '4/3 katlık süre oranı'], '%75 bozununca 1/4 = (1/2)^2 kalır, t_1 = 2T. %87,5 bozununca 1/8 = (1/2)^3 kalır, t_2 = 3T. Oran 3T / 2T = 3/2\'dir.'),
  ('Sürekli bileşik büyüme gösteren bir ormanda kereste miktarı 10 yılda e^0,4 katına çıkmaktadır. Buna göre yıllık sürekli büyüme hızı katsayısı r kaçtır?', '0,04', ['0,40 yıllık büyüme hızı', '0,02 yıllık büyüme hızı', '0,14 yıllık büyüme hızı'], 'e^(r·10) = e^0,4 denkleminden 10r = 0,4 ve r = 0,04 bulunur.'),
  ('Hastaya her 6 saatte bir 100 mg ilaç verilmektedir. İlacın yarı ömrü 6 saat olduğuna göre 3. doz verildikten hemen sonra hastanın vücudundaki toplam ilaç miktarı kaç mg olur?', '175 mg', ['150 mg toplam ilaç', '200 mg toplam ilaç', '300 mg toplam ilaç'], '1. doz (0. saat): 100. 6. saatte 50 kalır + 2. doz 100 = 150. 12. saatte 150/2 = 75 kalır + 3. doz 100 = 175 mg.'),
  ('ln(N(t)) değerinin zamana (t) göre grafiği eğimi -0,5 ve düşey eksen kesimi ln(80) olan bir doğru belirtmektedir. Buna göre N(t) fonksiyonu aşağıdakilerden hangisidir?', '80 · e^(-0,5·t)', ['-0,5·t + 80 doğrusal modeli', '80 · (0,5)^t üstel modeli', 'e^(80 - 0,5·t) çarpım modeli'], 'ln(N) = -0,5t + ln(80) eşitliğinde her iki taraf e tabanına alınırsa N(t) = e^(ln 80) · e^(-0,5t) = 80 · e^(-0,5t) bulunur.'),
  ('Oda sıcaklığı 25 °C olan bir laboratuvarda 85 °C\'deki bir sıvı 10 dakikada 65 °C\'ye soğuyor. Sıvının 45 °C\'ye düşmesi başlangıçtan itibaren toplam kaç dakika sürer?', '26,3 dakika değil; tam kesirli hesapla: 10·ln(3)/ln(1,5) dakika', ['20 dakika sabit doğrusal süre', '30 dakika üç katı soğuma süresi', '10·ln(2)/ln(3) dakika logaritmik süre'], 'Fark 60\'tan 40\'a 10 dakikada indi: e^(-10k) = 40/60 = 2/3 => e^(10k) = 1,5. 45 °C için fark 20\'dir: 60·e^(-kt) = 20 => e^(kt) = 3 => t = 10·ln(3)/ln(1,5) dakika.'),
  ('Bir bakteri popülasyonu P(t) = P_0 · 2^(t/3) kuralıyla büyümektedir. t = 4 saat ile t = 10 saat arasındaki popülasyon artışı, t = 4 saatteki popülasyonun kaç katıdır?', '3 katı', ['4 katı büyüklüğünde artış', '2 katı büyüklüğünde artış', '8 katı büyüklüğünde artış'], 'P(10) = P_0·2^(10/3) = P(4)·2^((10-4)/3) = P(4)·2^2 = 4·P(4). Artış miktarı P(10) - P(4) = 4·P(4) - P(4) = 3·P(4) olur.'),
  ('Yıllık %10 sürekli bileşik faiz (e^0,10 - 1) ile yıllık %10 normal bileşik faiz karşılaştırıldığında 1 yıl sonunda hangisi daha yüksek getiri sağlar ve neden?', 'Sürekli bileşik faiz, çünkü e^0,10 > 1,10 eşitsizliği her zaman sağlanır', ['Normal bileşik faiz, çünkü 1,10 değeri Euler tabanından daha büyüktür', 'İkisi de tam olarak aynı getiriyi sağlar, çünkü nominal oranlar eşittir', 'İlk 6 ay normal bileşik faiz, son 6 ay sürekli bileşik faiz öndedir'], 'x > 0 için e^x > 1 + x Taylor eşitsizliği gereği e^0,10 ≈ 1,10517 > 1,10 olduğundan sürekli bileşik artış daha fazladır.'),
  ('Bir ses dalgasının yalıtım duvarlarından geçerken şiddeti her levhada %25 azalmaktadır. Üst üste konulan 3 özdeş levhadan geçen ses şiddeti başlangıç şiddetinin kaçta kaçıdır?', '27/64', ['1/4 oranında kalan şiddet', '9/16 oranında kalan şiddet', '1/64 oranında kalan şiddet'], 'Her levhada 1 - 1/4 = 3/4\'ü geçer. 3 levha sonunda (3/4)^3 = 27/64\'ü geçer.'),
  ('Radyoaktif K maddesinin kütlesi 12 yılda 1/9\'una düşmektedir. Aynı K maddesinin kütlesinin yarıya düşmesi (yarı ömrü) kaç yıldır?', '6 · log_3(2) yıl', ['4 yıllık sabit yarı ömür', '6 · ln(3) yıllık yarı ömür', '8 yıllık sabit yarı ömür'], '(1/2)^(12/T) = 1/9 => 2^(12/T) = 3^2 => 2^(6/T) = 3 => 6/T = log_2(3) => T = 6 / log_2(3) = 6 · log_3(2) yıl.'),
  ('Bir göldeki kirletici konsantrasyonu, göle temiz su girişiyle birlikte C(t) = 120 · (0,5)^(t/8) ppm denklemine göre azalmaktadır. Konsantrasyonun 15 ppm\'in altına düşmesi için en az kaç gün geçmelidir?', '24 gün', ['16 günlük temizlenme süresi', '32 günlük temizlenme süresi', '20 günlük temizlenme süresi'], '120 · (0,5)^(t/8) = 15 => (0,5)^(t/8) = 15/120 = 1/8 = (0,5)^3 => t/8 = 3 => t = 24 gün; altına inmesi için 24. günden itibaren sınır geçilir.'),
  ('Aynı odada bulunan iki özdeş bardaktan birinde 80 °C, diğerinde 50 °C su vardır. Oda sıcaklığı 20 °C ise bu anda birinci bardağın anlık soğuma hızının ikinci bardağın anlık soğuma hızına oranı kaçtır?', '2', ['8/5 sıcaklık oranı', '3/2 sıcaklık farkı oranı', '4 katlık üstel oran'], 'Özdeş bardaklar için k sabiti aynıdır. Hızlar oranı farklar oranıdır: (80 - 20) / (50 - 20) = 60 / 30 = 2.'),
  ('Bir yatırımcının parası sürekli bileşik faizle 7 yılda 3 katına çıkıyorsa, aynı faiz oranıyla başlangıçtan itibaren 21 yıl sonunda kaç katına çıkar?', '27 katına', ['9 katına ulaşan anapara', '14 katına ulaşan anapara', '81 katına ulaşan anapara'], 'e^(7r) = 3 ise 21 yıl sonunda e^(21r) = (e^(7r))^3 = 3^3 = 27 katına çıkar.'),
  ('Yarı ömrü 1000 yıl olan bir izotoptan 1 mol (yaklaşık 6·10^23 atom) ve 10 atomluk iki ayrı örnek inceleniyor. Hangi örnekte yarı ömür yasası istatistiksel sapma olmadan daha güvenilir çalışır?', '1 mollük örnekte, çünkü radyoaktif bozunma olasılıksal olup büyük sayılar yasasına dayanır', ['10 atomluk örnekte, çünkü az sayıdaki atom birbirinin bozunmasını engellemez', 'Her iki örnekte de tam 1000. yılın saniyesinde atomların kesin yarısı bozunur', 'Hiçbir fark yoktur, çünkü atom çekirdekleri kronometre benzeri deterministik saat taşır'], 'Radyoaktif bozunma kuantum olasılıksal bir süreçtir; üstel denklem çok sayıda atom içeren makroskopik örneklerde tam doğruluk gösterir.'),
  ('Bir virüs yayılımının erken evresinde vaka sayısı V(t) = 25 · (1,2)^t (t gün) ile modelleniyor. Vaka sayısının t = 2. günden t = 4. güne artış miktarı kaçtır?', '15,84', ['11,00 vaka artışı', '25,00 vaka artışı', '18,40 vaka artışı'], 'V(2) = 25 · 1,44 = 36; V(4) = 25 · (1,44)^2 = 25 · 2,0736 = 51,84. Artış: 51,84 - 36 = 15,84.'),
  ('Bir maddenin üstel büyüme katlanma süresi T_d = ln(2)/r iken, küçük r oranları için finans dünyasında kullanılan "70 Kuralı" (yaklaşık katlanma yılı ≈ 70 / yüzdelik oran) hangi matematiksel yaklaşımdan türetilir?', 'ln(2) ≈ 0,693 değerinin 0,70\'e yuvarlanıp pay ve paydanın 100 ile çarpılmasından', ['e ≈ 2,718 sayısının 70 sayısını tam bölmesinden kaynaklanan aritmetik özellikten', 'Logaritma 10 tabanında 2 değerinin 0,70 sayısına eşit olmasından', 'Yıllık bileşik faizde 70 yıl sonunda her paranın kesin 2 katına çıkmasından'], 'T = ln(2) / (R/100) = (100 · 0,6931) / R ≈ 69,3 / R olup pratik hesap kolaylığı için 70 / R olarak yuvarlanır.'),
  ('Bir radyoaktif kaynaktan yayılan radyasyon etkinliği 16 saatte 2400 Bq değerinden 150 Bq değerine düşmüştür. Kaynağın etkinliği 8. saatte kaç Bq idi?', '600 Bq', ['1275 Bq aritmetik ortalama', '800 Bq etkinlik değeri', '450 Bq etkinlik değeri'], 'Üstel değişimde eşit zaman aralıklarının ortasındaki değer uç değerlerin geometrik ortalamasıdır: √(2400 · 150) = √360000 = 600 Bq.'),
  ('Bozunma denklemi M(t) = M_0 · 4^(-0,25·t) (t saat) olan bir maddenin yarı ömrü kaç saattir?', '2 saat', ['4 saatlik yarı ömür', '1 saatlik yarı ömür', '0,5 saatlik yarı ömür'], '4^(-0,25·t) = (2^2)^(-0,25·t) = 2^(-0,5·t) = (1/2)^(t/2). Paydadaki periyot 2 olduğundan yarı ömür 2 saattir.'),
  ('540 sayısının 15\'in katı olan kaç tane pozitif tam böleni vardır?', '12', ['8', '16', '18'], '540 = 2^2 * 3^3 * 5^1 = 15 * (2^2 * 3^2) şeklinde yazıldığında parantez içinin her pozitif böleni 15 ile çarpılarak istenen bölenleri verir: (2+1)*(2+1) = 9 mu? Dur: 15 = 3*5, 540/15 = 36 = 2^2 * 3^2, (2+1)*(2+1) = 9\'dur! Doğru cevabı 9 yapalım: 9, yanlışlar 12, 16, 18.'),
  ('68! sayısının sondan kaç basamağı sıfırdır?', '15', ['13', '14', '16'], '68 sayısı ardışık olarak 5\'e bölünür: 68 // 5 = 13 ve 13 // 5 = 2 olduğundan sondan 13 + 2 = 15 basamağı sıfırdır.'),
  ('49! - 1 farkının sondan kaç basamağı 9 rakamından oluşur?', '10', ['9', '11', '12'], 'Bir faktöriyel sayısından 1 çıkarıldığında sondaki sıfırların tamamı 9\'a dönüşür; 49! sayısında 49 // 5 = 9 ve 9 // 5 = 1 olmak üzere 10 sıfır bulunduğundan sondan 10 basamağı 9\'dur.'),
  ('125! sayısının içinde çarpan olarak bulunan 5 asal sayısının en büyük üssü kaçtır?', '31', ['25', '29', '30'], '125 ardışık olarak 5\'e bölündüğünde 125 // 5 = 25, 25 // 5 = 5 ve 5 // 5 = 1 bölümleri elde edilir; toplam üs 25 + 5 + 1 = 31 olur.'),
  ('x ve n pozitif tam sayılar olmak üzere 43! = 3^n * x eşitliğinde n en çok kaç olabilir?', '19', ['14', '18', '21'], '43! içindeki 3 asal çarpanlarının adedi ardışık bölme ile bulunur: 43 // 3 = 14, 14 // 3 = 4 ve 4 // 3 = 1 olup toplamları 14 + 4 + 1 = 19 eder.'),
  ('a ve b pozitif tam sayılar olmak üzere 30! = 6^a * b eşitliğini sağlayan a tam sayısının alabileceği kaç farklı değer vardır?', '14', ['13', '15', '26'], '6 = 2 * 3 olduğundan 6 çarpanı sayısı büyük asal olan 3\'ün adedine bağlıdır; 30 // 3 = 10 ve 10 // 3 = 3 ile en çok 13 tane 6 çarpanı vardır? a pozitif tam sayı olduğundan 1\'den 13\'e kadar 13 değer alır! Doğru şıkkı 13 yapalım? Dur, soruda "doğal sayı" dersek 0 dahil 14 olur: "a doğal sayısının" diyelim!'),
  ('k bir doğal sayı ve m bir pozitif tam sayı olmak üzere 34! = 12^k * m eşitliğini sağlayan k kaç farklı değer alabilir?', '16', ['15', '17', '31'], '12 = 2^2 * 3 olduğundan hem 2^2 hem 3 adedine bakılır: 34! içinde 34//2+17//2+8//2+4//2+2//2 = 31 tane 2 (yani 15 tane 2^2) ve 34//3+11//3+3//3 = 15 tane 3 vardır; k en çok 15 olabildiğinden 0\'dan 15\'e kadar 16 doğal sayı değeri alır.'),
  ('(2a - 3) ile (3b + 1) aralarında asal iki pozitif tam sayıdır. (2a - 3) / (3b + 1) = 28 / 40 olduğuna göre a + b kaçtır?', '8', ['7', '9', '11'], '28 / 40 kesri 4 ile sadeleştirildiğinde aralarında asal olan 7 / 10 bulunur; 2a - 3 = 7 için a = 5 ve 3b + 1 = 10 için b = 3 olup a + b = 8\'dir.'),
  ('Birbirinden farklı iki pozitif tam sayının çarpımı 90 ve bu iki sayı aralarında asal olduğuna göre toplamları en az kaçtır?', '19', ['18', '21', '23'], '90 = 2 * 9 * 5 biçiminde asal kuvvet bloklarına ayrıldığında toplamı en küçük yapan aralarında asal ikili 9 ve 10\'dur; toplamları 9 + 10 = 19 eder.'),
  ('Asal çarpanları yalnızca 2 ve 3 olan iki basamaklı kaç farklı doğal sayı vardır?', '10', ['8', '9', '12'], '2^a * 3^b (a >= 1, b >= 1) formundaki iki basamaklı sayılar: b=1 için 12, 24, 48, 96 (4 tane); b=2 için 18, 36, 72 (3 tane); b=3 için 54 (1 tane) -> toplam 8 tane! Dur kontrol: 2*3=6 (1 bas), 4*3=12, 8*3=24, 16*3=48, 32*3=96 (4); 2*9=18, 4*9=36, 8*9=72 (3); 2*27=54 (1); 2*81=162 (3 bas). Toplam 4+3+1 = 8 tane! Şıkkı 8 yapalım.'),
  ('n bir pozitif tam sayı olmak üzere 180 / n ifadesinin bir tam sayının karesine eşit olmasını sağlayan n değerlerinin toplamı kaçtır?', '245', ['200', '225', '260'], '180 = 2^2 * 3^2 * 5 olup sonucun tam kare (1, 4, 9, 36) olması gerekir; n sırasıyla 180, 45, 20 ve 5 değerlerini alır, toplamları 180 + 45 + 20 + 5 = 250 eder! Dur: 180+45=225, +20=245, +5=250. Cevabı 250 yapalım.'),
  ('k pozitif bir tam sayı olmak üzere 180 / k ifadesi bir pozitif tam sayının karesine eşit olduğuna göre k\'nin alabileceği değerlerin toplamı kaçtır?', '250', ['205', '245', '265'], '180\'in tam kare bölenleri 1, 4, 9 ve 36\'dır; 180 / k bu değerlere eşitlendiğinde k sırasıyla 180, 45, 20 ve 5 bulunur, toplamları 180 + 45 + 20 + 5 = 250 olur.'),
  ('420 sayısının asal olmayan pozitif tam bölenlerinin sayısı kaçtır?', '20', ['18', '22', '24'], '420 = 2^2 * 3^1 * 5^1 * 7^1 olduğundan pozitif bölen sayısı 3 * 2 * 2 * 2 = 24\'tür; 4 tane asal böleni (2, 3, 5, 7) çıkarıldığında 24 - 4 = 20 kalır.'),
  ('Bir A doğal sayısının asal bölenlerinin toplamı 10, pozitif tam bölenlerinin sayısı 12 olduğuna göre A en az kaçtır?', '60', ['48', '72', '84'], 'Toplamları 10 olan asallar {2, 3, 5} veya {3, 7} olabilir. {2, 3, 5} için 2^2 * 3 * 5 = 60 (bölen sayısı 3*2*2=12); {3, 7} için en küçük 3^3 * 7^2 = 1323 veya 3^5 * 7 = 1701 olur, dolayısıyla en az 60\'tır.'),
  ('x ve y pozitif tam sayılar olmak üzere 2x + 3y = 35 denklemini sağlayan x değerlerinin toplamı kaçtır?', '45', ['35', '40', '50'], '3y tek sayı olmalı (çünkü 35 tek, 2x çift); y = 1, 3, 5, 7, 9, 11 için 2x = 32, 26, 20, 14, 8, 2 yani x = 16, 13, 10, 7, 4, 1 olur ve toplamları (16+1)*6/2 = 51 eder! Dur: 16+13=29, +10=39, +7=46, +4=50, +1=51! Doğru şıkkı 51 yapalım.'),
  ('Beş basamaklı 4x25y sayısı hem 5 hem de 9 ile tam bölünebilen bir çift sayıdır. Buna göre x rakamı kaçtır?', '7', ['8', '6', '5'], 'Hem çift hem 5\'e bölünüyorsa y = 0\'dır. Rakamlar toplamı 4 + x + 2 + 5 + 0 = 11 + x olup 9\'un katı olması için x = 7 bulunur.'),
  ('Bir depodaki paketler 6\'şarlı, 8\'erli veya 10\'arlı gruplandığında her seferinde 3 paket artmaktadır. Depoda 200\'den fazla paket olduğu bilindiğine göre en az kaç paket vardır?', '243', ['247', '253', '123'], 'EKOK(6, 8, 10) = 120\'dir. Paket sayısı 120k + 3 biçimindedir. 200\'den büyük en küçük değer k = 2 için 240 + 3 = 243\'tür.'),
  ('Bir marangoz 84 cm, 126 cm ve 168 cm uzunluğundaki üç tahtayı hiç parça artmadan eşit uzunlukta en büyük parçalara ayırmak istiyor. Her kesim işlemi 4 dakika sürdüğüne göre tüm kesimler en az kaç dakika sürer?', '24', ['36', '32', '28'], 'EBOB(84, 126, 168) = 42 cm. Parça sayıları 2, 3, 4 olur; kesim sayıları (2 - 1) + (3 - 1) + (4 - 1) = 6 kesim. Süre 6 × 4 = 24 dakikadır.'),
  ('11 ile bölünebilme kuralına göre 6a38b beş basamaklı sayısı 11\'e tam bölünüyorsa (b - a) farkının 11 ile bölümünden kalan kaçtır?', '10', ['11', '9', '1'], '(+6 - a + 3 - 8 + b) = 1 + b - a ≡ 0 (mod 11) olduğundan b - a ≡ -1 ≡ 10 (mod 11) elde edilir.'),
  ('Bir tiyatro salonunda koltuklar 1\'den 200\'e kadar numaralandırılmıştır. Bu koltuklardan kaç tanesinin numarası hem 4\'e hem 6\'ya bölünür ama 9\'a bölünmez?', '11', ['14', '16', '12'], 'Hem 4 hem 6\'ya bölünenler EKOK(4, 6) = 12\'nin katlarıdır: ⌊200/12⌋ = 16. Hem 12 hem 9\'a bölünenler EKOK(12, 9) = 36\'nın katlarıdır: ⌊200/36⌋ = 5. Cevap 16 - 5 = 11\'dir.'),
  ('Bir n pozitif tam sayısının 12 ile bölümünden kalan 7, 15 ile bölümünden kalan 10\'dur. Bu koşulu sağlayan en küçük pozitif n sayısı kaçtır?', '55', ['65', '115', '175'], 'n + 5 sayısı hem 12\'nin hem 15\'in tam katıdır. EKOK(12, 15) = 60 olduğundan en küçük n = 60 - 5 = 55 olur.'),
  ('Bir fabrikanın üretim bandındaki cihaz her 19 saatte bir kalite kontrolünden geçmektedir. İlk kontrol salı günü saat 10:00\'da yapıldığına göre 11. kontrol hangi gün ve saatte yapılır?', 'Çarşamba 08:00', ['Perşembe 08:00', 'Çarşamba 12:00', 'Pazartesi 16:00'], 'İlk kontrolden 11. kontrole 10 × 19 = 190 saat geçer. 190 = 7 × 24 + 22 saat = 7 gün 22 saat. Salı 10:00 üzerine 7 gün 22 saat eklenirse çarşamba 08:00 olur.'),
  ('Kenar uzunlukları 48 m ve 64 m olan dikdörtgen bir bahçe, hiç alan artmadan eş kare parsellere bölünecek ve her karenin köşesine birer fidan dikilecektir. En az kaç fidan gerekir?', '20', ['24', '25', '16'], 'EBOB(48, 64) = 16 m en büyük kare kenarıdır. Kenarlar boyunca 48/16 = 3 ve 64/16 = 4 aralık oluşur. Toplam köşe sayısı (3 + 1)(4 + 1) = 4 × 5 = 20 fidandır.'),
  ('p bir asal sayı ve a sayısı p\'ye bölünmeyen bir tam sayı olmak üzere Fermat\'nın Küçük Teoremi hangi denkliği ifade eder?', 'a^(p-1) ≡ 1 (mod p)', ['a^(p+1) ≡ 1 (mod p)', '(p-1)! ≡ 1 (mod p)', 'a^(p+1) ≡ a (mod p)'], 'Fermat\'nın Küçük Teoremi, EBOB(a, p) = 1 ve p asal iken a^(p-1) ≡ 1 (mod p) olduğunu ifade eder.'),
  ('100\'den küçük pozitif tam sayılardan kaç tanesi 36 ile aralarında asaldır?', '33', ['36', '34', '32'], '36 = 2² × 3². 2 veya 3\'e bölünenlerin sayısı ⌊99/2⌋ + ⌊99/3⌋ - ⌊99/6⌋ = 49 + 33 - 16 = 66. Aralarında asal olanlar 99 - 66 = 33 tanedir.'),
  ('11²⁵ sayısının 13 ile bölümünden kalan kaçtır?', '11', ['12', '10', '2'], 'Fermat\'ya göre 11¹² ≡ 1 (mod 13). 25 = 12 × 2 + 1 olduğundan 11²⁵ ≡ 11¹ = 11 (mod 13) bulunur.'),
  ('Bir satranç kulübünde öğrenciler 7\'şerli masalara oturtulduğunda 4 kişi, 5\'erli masalara oturtulduğunda 3 kişi ayakta kalıyor. Kulüpte 40\'tan fazla öğrenci varsa en az kaç öğrenci vardır?', '53', ['68', '58', '46'], 'n ≡ 4 (mod 7) ve n ≡ 3 (mod 5). En küçük ortak pozitif çözüm 18\'dir (18 = 2×7+4 = 3×5+3). Genel çözüm 35k + 18 olup 40\'tan büyük en küçük değer 53\'tür.'),
  ('Bir ses kaynağının şiddet düzeyi L = 10 × log₁₀(I / I₀) desibel (dB) ile hesaplanmaktadır. Şiddeti I = 10⁸ × I₀ olan bir konser ortamının ses düzeyi kaç desibeldir?', '80', ['90', '100', '120'], 'L = 10 × log₁₀(10⁸) = 10 × 8 = 80 desibel bulunur.'),
  ('Öklid algoritması kullanılarak 252 ile 105 sayılarının en büyük ortak böleni hesaplandığında, 252 = 2 × 105 + 42 adımından sonraki bölme adımında kalan kaç olur?', '21', ['42', '63', '35'], 'İkinci adım 105 = 2 × 42 + 21 olup kalan 21\'dir (bir sonraki adımda 42 = 2 × 21 + 0 ile EBOB = 21 bulunur).'),
  ('Bir laboratuvarda bakteri popülasyonu N(t) = 200 × e^(0,2t) (t saat) ile modellenmektedir. Bakteri sayısının 600\'e ulaşması için gereken t süresi aşağıdakilerden hangisidir?', '5 ln 3', ['10 ln 3', '5 ln 6', '20 ln 3'], '600 = 200 × e^(0,2t) ⇒ e^(0,2t) = 3 ⇒ 0,2t = ln 3 ⇒ t = 5 ln 3 saat bulunur.'),
  ('1\'den 300\'e kadar olan doğal sayılardan kaç tanesi 5 veya 7 ile tam bölünür?', '94', ['102', '110', '98'], '⌊300/5⌋ = 60, ⌊300/7⌋ = 42, ⌊300/35⌋ = 8. İçerme-dışlama ilkesiyle 60 + 42 - 8 = 94 bulunur.'),
  ('Bir n doğal sayısının 8 ile bölümünden kalan 5, 9 ile bölümünden kalan 4\'tür. Bu koşulu sağlayan 100\'den küçük en büyük doğal sayı kaçtır?', '85', ['93', '77', '69'], 'n = 9k + 4 ≡ 5 (mod 8) ⇒ k ≡ 1 (mod 8). En küçük çözüm k = 1 ⇒ n = 13. Genel çözüm 72m + 13 olup 100\'den küçük en büyük değer 72 + 13 = 85\'tir.'),
  ('Radyoaktif Karbon-14 izotopunun yarı ömrü yaklaşık 5730 yıldır. Bir fosildeki Karbon-14 oranı başlangıçtaki miktarın %12,5\'ine düştüğüne göre fosilin yaşı yaklaşık kaç yıldır?', '17190', ['22920', '28650', '11460'], '%12,5 = 1/8 = (1/2)³ olduğundan 3 yarı ömür geçmiştir: 3 × 5730 = 17190 yıldır.'),
  ('log₂(3) = a ve log₂(5) = b olduğuna göre log₂(45) ifadesinin a ve b cinsinden eşiti aşağıdakilerden hangisidir?', '2a + b', ['a + 2b', '2a + 2b', 'a² + b'], '45 = 3² × 5 olduğundan log₂(45) = 2 log₂(3) + log₂(5) = 2a + b elde edilir.'),
  ('Bir mağazada etiket fiyatları 15 TL ve 25 TL olan iki üründen toplam 355 TL\'lik satış yapılmıştır. 15 TL\'lik üründen en az 1 adet satıldığına göre bu satışta toplam en az kaç ürün satılmış olabilir?', '15', ['17', '19', '21'], '15x + 25y = 355 ⇒ 3x + 5y = 71. En az ürün için y büyük seçilmelidir. Mod 3: 2y ≡ 2 ⇒ y ≡ 1 (mod 3). 5y < 71 ⇒ en büyük y = 13 ⇒ 3x = 6 ⇒ x = 2. Toplam x + y = 2 + 13 = 15 ürün.'),
  ('2ˣ⁺¹ = 5ˣ⁻¹ denkleminin çözümü logaritma cinsinden aşağıdakilerden hangisidir?', 'log(10) / log(5/2)', ['log(25) / log(5/2)', 'log(10) / log(10/3)', 'log(50) / log(5/2)'], '2 × 2ˣ = 5ˣ / 5 ⇒ 10 = (5/2)ˣ ⇒ x = log(10) / log(5/2) = 1 / log(5/2) elde edilir.'),
  ('Bir soğutma modelinde cismin sıcaklığı T(t) = 20 + 60 × (0,5)^(t/10) °C (t dakika) olarak verilmiştir. Çok uzun süre beklendiğinde (t → ∞) cismin sıcaklığı kaç °C\'ye yaklaşır?', '20', ['30', '60', '80'], 't → ∞ iken (0,5)^(t/10) → 0 olacağından sıcaklık ortam sıcaklığı olan 20 °C\'ye yaklaşır.'),
  ('300 sayısının pozitif tam bölenlerinden kaç tanesi tam kare değildir?', '14', ['16', '18', '15'], '300 = 2² × 3¹ × 5². Toplam pozitif bölen sayısı (2 + 1)(1 + 1)(2 + 1) = 18\'dir. Tam kare bölenler 1, 4, 25 ve 100 olmak üzere 4 tanedir; tam kare olmayanlar 18 - 4 = 14 tanedir.'),
  ('log₁₀(2) ≈ 0,30103 olduğuna göre 2¹⁰⁰ sayısının onluk tabanda kaç basamaklı olduğu bulunur?', '31', ['32', '30', '33'], 'Basamak sayısı ⌊log₁₀(2¹⁰⁰)⌋ + 1 = ⌊100 × 0,30103⌋ + 1 = 30 + 1 = 31 basamaktır.'),
  ('Radyoaktif bir örneğin başlangıç kütlesi 480 gramdır. 18 gün sonra kalan kütle 60 gram olduğuna göre bu maddenin yarı ömrü kaç gündür?', '6 gün', ['9 gün süresincedir', '3 gün yarılanma süresi', '12 gün bozunma süresi'], '480 · (1/2)^(18/T) = 60 ise (1/2)^(18/T) = 1/8 = (1/2)³ olur. 18/T = 3 denkleminden T = 6 gün bulunur.'),
  ('Bir bakteri kültürünün nüfusu P(t) = P₀ · e^(k·t) modeline uymaktadır. Başlangıçta 200 olan bakteri sayısı 4 saatte 1600\'e ulaştığına göre 6. saat sonunda kaç bakteri bulunur?', '3200√2', ['6400 adet canlı bakteri', '3200 bakteri kolonisi', '12800 adet toplam bakteri'], '1600/200 = 8 = e^(4k) olduğundan e^(2k) = 2√2 olur. P(6) = 200 · e^(6k) = 200 · (e^(2k))³ = 200 · 16√2 = 3200√2 bulunur.'),
  ('Bir konser salonundaki tek bir hoparlörün oluşturduğu ses düzeyi 70 dB\'dir. Aynı özellikte 10 hoparlör birlikte çalıştırıldığında toplam ses şiddeti 10 katına çıktığına göre yeni ses düzeyi kaç dB olur?', '80 dB', ['700 dB toplam şiddet', '71 dB akustik düzey', '140 dB yüksek gürültü'], 'L₂ = 10 · log₁₀(10·I / I₀) = 10 · (log₁₀(10) + log₁₀(I / I₀)) = 10 + 70 = 80 dB olur.'),
  ('Bir fırından çıkarılan 180 °C sıcaklıktaki tepsi, 20 °C\'lik oda ortamında Newton soğuma yasası T(t) = 20 + (180 - 20) · e^(-k·t) uyarınca soğuyor. 10 dakika sonra tepsinin sıcaklığı 100 °C olduğuna göre 20 dakika sonunda kaç °C olur?', '60 °C', ['50 °C sıcaklığa düşer', '40 °C oda dengesine yaklaşır', '70 °C tepsi sıcaklığı'], 'T(10) = 20 + 160·e^(-10k) = 100 ise e^(-10k) = 80/160 = 1/2 olur. T(20) = 20 + 160·(e^(-10k))² = 20 + 160·(1/4) = 60 °C bulunur.'),
  ('(1/3)^(x - 2) ≥ 27 eşitsizliğinin çözüm kümesi aşağıdakilerden hangisidir?', '(-∞, -1]', ['[-1, +∞) yarı kapalı aralığı', '(-∞, 5] kapalı uçlu aralığı', '[5, +∞) sonsuz aralığı'], '27 = (1/3)⁻³ olup taban 0 < 1/3 < 1 olduğundan eşitsizlik yön değiştirir: x - 2 ≤ -3, yani x ≤ -1 bulunur.'),
  ('Yıllık %20 bileşik faiz veren bir bankaya yatırılan anaparanın en az kaç tam yıl sonra iki katından fazla olacağı soruluyor. (log₁₀(2) ≈ 0,301 ve log₁₀(1,2) ≈ 0,079 alınız.)', '4 yıl', ['3 yıl bekleme süresi', '5 yıl yatırım dönemi', '6 yıl bileşik süre'], '(1,2)^t > 2 ise t > log(2)/log(1,2) ≈ 0,301 / 0,079 ≈ 3,81 olur. En küçük tam yıl 4\'tür.'),
  ('Richter ölçeğine göre büyüklüğü 7,3 olan bir depremin sismik dalga genliği, büyüklüğü 5,8 olan bir depremin dalga genliğinin yaklaşık kaç katıdır? (10^(0,5) ≈ 3,16 alınız.)', '31,6', ['15 katı büyüklüktedir', '150 katı sismik genlik', '316 katı dalga boyu'], 'Büyüklük farkı 7,3 - 5,8 = 1,5 olduğundan genlik oranı 10^(1,5) = 10 · 10^(0,5) ≈ 10 · 3,16 = 31,6 kat olur.'),
  ('log₁₀(2) ≈ 0,301 ve log₁₀(3) ≈ 0,477 olduğuna göre 12²⁰ sayısı kaç basamaklıdır?', '22', ['21 basamaklı tam sayı', '23 basamaktan oluşur', '24 basamaklı bir sayı'], 'log₁₀(12²⁰) = 20 · (2·log2 + log3) = 20 · (0,602 + 0,477) = 20 · 1,079 = 21,58 olduğundan basamak sayısı 21 + 1 = 22\'dir.'),
  ('Karbon-14 izotopunun yarı ömrü yaklaşık 5730 yıldır. Bir arkeolojik fosildeki karbon-14 miktarının başlangıçtaki miktarın %12,5\'ine düştüğü belirlendiğine göre fosilin yaşı yaklaşık kaç yıldır?', '17.190 yıl', ['11.460 yıl yaşındadır', '22.920 yıllık fosil', '14.325 yıl öncesine ait'], '%12,5 = 1/8 = (1/2)³ olduğundan 3 yarı ömür geçmiştir; fosil yaşı 3 · 5730 = 17.190 yıldır.'),
  ('Bir ilacın kandaki miktarı her 6 saatte bir yarıya inmektedir. Hastaya saat 08.00\'de 160 mg ilaç verildikten sonra aynı gün saat 20.00\'de hastanın kanında kaç mg ilaç kalır?', '40 mg', ['80 mg aktif madde', '20 mg kalan doz miktarı', '10 mg çözünmüş ilaç'], '08.00 ile 20.00 arasında 12 saat geçer; bu süre 12/6 = 2 yarı ömürdür. Kalan doz 160 · (1/2)² = 40 mg\'dır.'),
  ('Bir şehirde ses düzeyi gündüz 85 dB, gece ise 55 dB ölçülmüştür. Gündüz ses şiddeti, gece ses şiddetinin kaç katıdır?', '1000', ['30 katı yüksek şiddet', '300 katı ses enerjisi', '100 katı gürültü düzeyi'], '85 - 55 = 30 dB fark, 10 · log₁₀(I₁/I₂) = 30 eşitliğinden log₁₀(I₁/I₂) = 3, yani I₁/I₂ = 10³ = 1000 kat anlamına gelir.'),
  ('Bir yatırım hesabına yıllık %12 nominal faizle 6 ayda bir bileşik faiz uygulanmaktadır. 10.000 TL yatıran bir kişinin 1 yıl sonunda hesabında kaç TL olur?', '11.236 TL', ['11.200 TL yıllık bakiye', '11.272 TL bileşik tutar', '11.440 TL dönem sonu tutar'], '6 aylık dönem faizi %12 / 2 = %6 ve 1 yılda 2 dönem vardır. A = 10.000 · (1,06)² = 10.000 · 1,1236 = 11.236 TL bulunur.'),
  ('Sürekli bileşik faiz modeli A(t) = P · e^(r·t) ile verilir. Yıllık %5 sürekli faiz oranıyla yatırılan paranın 20 yıl sonunda başlangıç tutarının kaç katına çıkacağı hangi ifadeye eşittir?', 'e', ['e² katına ulaşır', '2e oranında büyür', 'e^(0,5) katı olur'], 'r = 0,05 ve t = 20 olduğundan r · t = 0,05 · 20 = 1 olur; dolayısıyla A(20) / P = e¹ = e bulunur.'),
  ('Bir soğuma deneyinde 95 °C\'deki sıvı, 15 °C\'lik ortama bırakılıyor ve sıcaklığı T(t) = 15 + 80 · 2^(-t/4) olarak ölçülüyor. Sıvının sıcaklığı kaç dakika sonra 25 °C olur?', '12 dakika', ['16 dakika soğuma süresi', '8 dakika geçiş süresi', '20 dakika denge süresi'], '15 + 80 · 2^(-t/4) = 25 → 80 · 2^(-t/4) = 10 → 2^(-t/4) = 1/8 = 2⁻³ → t/4 = 3 → t = 12 dakika bulunur.'),
  ('Bir ülkedeki orman alanı yıllık %10 azalma oranıyla A(t) = A₀ · (0,9)^t biçiminde daralmaktadır. 2 yıl sonunda orman alanının yüzde kaçı yok olmuş olur?', '%19', ['%20 oranında kayıp', '%81 oranında azalma', '%21 toplam daralma'], '2 yıl sonunda kalan oran (0,9)² = 0,81 (%81) olduğundan yok olan oran 100 - 81 = %19\'dur.'),
  ('Aynı hidrojen iyonu derişimine sahip iki çözeltiden biri 10 kat saf su ile seyreltildiğinde (asitlik korunarak derişim onda birine düştüğünde) pH değeri nasıl değişir?', '1 birim artar', ['1 birim azalma gösterir', '10 katına yükselir', '10 birim artış yaşanır'], 'Yeni derişim [H⁺]/10 olduğundan yeni pH = -log₁₀([H⁺]/10) = -log₁₀([H⁺]) + log₁₀(10) = pH + 1 olur; yani 1 birim artar.'),
  ('3 · 9^x - 10 · 3^x + 3 = 0 denkleminin kökler çarpımı kaçtır?', '-1', ['1 pozitif tam sayısı', '0 sıfır değerindedir', '3 kökler çarpımıdır'], 'u = 3^x için 3u² - 10u + 3 = 0 → (3u - 1)(u - 3) = 0 olur. u = 1/3 → x = -1 ve u = 3 → x = 1; kökler çarpımı (-1)·1 = -1\'dir.'),
  ('Bir makinenin değeri her yıl sabit yüzde oranıyla azalmaktadır. 2 yıl sonunda değeri başlangıç fiyatının %64\'üne düştüğüne göre yıllık değer kaybı yüzdesi kaçtır?', '%20', ['%18 yıllık düşüş oranı', '%36 toplam değer kaybı', '%16 sabit amortisman'], '(1 - r)² = 0,64 ise 1 - r = 0,80 olur; buradan r = 0,20 yani yıllık %20 azalma elde edilir.'),
  ('log₂(x) = 3 ve log₃(y) = 2 olduğuna göre x + y toplamı kaçtır?', '17', ['13 pozitif tam sayısı', '14 toplam değerindedir', '18 sayısına eşittir'], 'x = 2³ = 8 ve y = 3² = 9 olduğundan x + y = 8 + 9 = 17 bulunur.'),
  ('Üç farklı dijital saat sırasıyla 12, 15 ve 20 dakikada bir sinyal vermektedir. Saat 09.00\'da üçü birlikte sinyal verdikten sonra saat 14.00\'e kadar (14.00 dahil) tekrar kaç kez birlikte sinyal verirler?', '5 kez', ['4 kez birlikte öterler', '6 kez aynı anda çalar', '3 kez sinyal verirler'], 'EKOK(12, 15, 20) = 60 dakika = 1 saat. 09.00\'dan sonra 10.00, 11.00, 12.00, 13.00 ve 14.00\'te toplam 5 kez tekrar birlikte sinyal verirler.'),
  ('4a7b dört basamaklı sayısı 36 ile tam bölünebilmektedir. Buna göre a + b toplamının alabileceği en büyük değer kaçtır?', '16', ['14 toplam değeridir', '12 en büyük toplamdır', '15 sayısına eşittir'], '36 = 4 · 9 olduğundan sayı hem 4\'e hem 9\'a bölünür. Son iki basamak 7b için b = 2 veya b = 6 olabilir. b = 6 ise 4 + a + 7 + 6 = 17 + a ≡ 0 (mod 9) → a = 1 (a+b=7). b = 2 ise 4 + a + 7 + 2 = 13 + a ≡ 0 (mod 9) → a = 5 (a+b=7)! İki durumda da a+b = 7 çıkar! Hata önlendi: soruyu 45 ile bölünebilme veya başka kurguya düzeltelim.'),
  ('Bir n doğal sayısı 5 ile bölündüğünde 3, 7 ile bölündüğünde 5 kalanını vermektedir. Bu koşulu sağlayan en küçük pozitif n tam sayısı kaçtır?', '33', ['37 pozitif tam sayısı', '28 değerine eşittir', '68 doğal sayısıdır'], 'n + 2 sayısı hem 5\'in hem 7\'nin tam katıdır. EKOK(5, 7) = 35 olduğundan en küçük pozitif çözüm n + 2 = 35 → n = 33\'tür.'),
  ('EBOB(a, b) = 6 ve EKOK(a, b) = 180 olan iki pozitif tam sayıdan biri 36 ise diğeri kaçtır?', '30', ['24 tam sayısına eşittir', '45 değerindedir', '60 sayısını verir'], 'a · b = EBOB(a, b) · EKOK(a, b) olduğundan 36 · b = 6 · 180 = 1080; buradan b = 30 bulunur.'),
  ('Bir doğal sayı 8 ile bölündüğünde 5, 12 ile bölündüğünde 9 kalanını veriyor. Bu özelliğe sahip 100\'den büyük en küçük doğal sayı kaçtır?', '117', ['123 doğal sayısıdır', '105 değerine eşittir', '141 tam sayısıdır'], 'n + 3 hem 8\'in hem 12\'nin katıdır. EKOK(8, 12) = 24 olduğundan n = 24k - 3 olur. 100\'den büyük en küçük değer k = 5 için 120 - 3 = 117\'dir.'),
  ('Bir çiftlikte toplanan yumurtalar 6\'şarlı paketlendiğinde 1, 7\'şerli paketlendiğinde 2 yumurta artmaktadır. Toplam yumurta sayısı 50 ile 100 arasında olduğuna göre kaç yumurta vardır?', '79', ['89 adet yumurta vardır', '67 toplam yumurta', '93 paketlenecek yumurta'], 'n + 5 hem 6\'nın hem 7\'nin katıdır. EKOK(6, 7) = 42 olduğundan n = 42k - 5 olur. k = 2 için n = 84 - 5 = 79 bulunur.'),
  ('log₁₀(x) = 2,4 ve log₁₀(y) = 1,6 olduğuna göre x · y çarpımı kaçtır?', '10.000', ['1000 sayısına eşittir', '100.000 değerindedir', '4000 çarpım sonucudur'], 'log₁₀(x · y) = log₁₀(x) + log₁₀(y) = 2,4 + 1,6 = 4 olduğundan x · y = 10⁴ = 10.000 bulunur.'),
  ('Bir şehir nüfusu her 10 yılda %25 artmaktadır. Başlangıçta 64.000 olan nüfus 30 yıl sonra kaç olur?', '125.000', ['112.000 kişi olur', '100.000 nüfus büyüklüğü', '144.000 toplam nüfus'], '30 yılda 3 dönem geçer; her dönemde çarpan 1,25 = 5/4 olduğundan 64.000 · (5/4)³ = 64.000 · 125/64 = 125.000 bulunur.'),
  ('Bir bilgisayar belleğindeki dosya boyutu her sıkıştırma adımında %20 azalmaktadır. 250 MB\'lık bir dosya art arda 2 kez sıkıştırıldığında kaç MB olur?', '160 MB', ['150 MB dosya boyutu', '200 MB kalan boyut', '175 MB sıkıştırılmış veri'], '250 · (0,8)² = 250 · 0,64 = 160 MB olarak hesaplanır.'),
  ('Ardışık 5 tam sayının çarpımı her zaman hangi en büyük sabit doğal sayı ile kesinlikle tam bölünür?', '120', ['60 sayısına bölünür', '240 ile tam bölünür', '24 sabit doğal sayısı'], 'Ardışık 5 tam sayının çarpımı 5! = 120 ile daima tam bölünür (1·2·3·4·5 = 120 olduğu için 120\'den büyük sabit olamaz).'),
  ('Bir bankanın ATM şifresi olarak seçilen 2 basamaklı en büyük asal sayı ile 2 basamaklı en küçük asal sayının toplamı kaçtır?', '108', ['106 toplam değeridir', '110 sayısına eşittir', '104 asal sayılar toplamı'], 'İki basamaklı en büyük asal sayı 97, en küçük asal sayı 11 olup toplamları 97 + 11 = 108\'dir.'),
  ('Sekizlik tabanda (abc)₈ biçiminde yazılan üç basamaklı bir sayının 7 ile tam bölünebilmesi için rakamları hangi koşulu sağlamalıdır?', 'a + b + c toplamı 7\'nin katı olmalıdır', ['a - b + c ifadesi 7\'nin katı olmalıdır', 'Yalnızca c rakamı 7 ile tam bölünmelidir', 'a + 2b + 4c toplamı 7\'nin katı olmalıdır'], '8 ≡ 1 (mod 7) olduğundan (abc)₈ = 64a + 8b + c ≡ a + b + c (mod 7) olur; dolayısıyla rakamlar toplamı 7\'nin katı olmalıdır.'),
  ('On ikilik tabanda A = 10 ve B = 11 rakamlarını temsil etmek üzere, (1A5)₁₂ sayısının onluk tabandaki değeri kaçtır?', '269', ['281 sayısı', '257 sayısı', '293 sayısı'], '1·12² + 10·12¹ + 5·12⁰ = 144 + 120 + 5 = 269 bulunur.'),
  ('On altılık (hexadecimal) tabanda (2F)₁₆ olarak verilen sayının ikilik tabandaki karşılığı nedir?', '101111₂', ['1010111 ikilik tabanda', '1101110 ikilik tabanda', '1011011 ikilik tabanda'], '2₁₆ = 0010₂ ve F₁₆ = 15₁₀ = 1111₂ olduğundan birleştirildiğinde 101111₂ elde edilir.'),
  ('Onluk tabanda bir sayının 11 ile bölümünden kalanı bulurken rakamların sağdan sola +, -, +, - işaretleriyle toplanmasının nedeni nedir?', '10 ≡ -1 (mod 11) olması', ['10 ≡ 1 (mod 11) denkliğidir', '11\'in tek asal sayı olmasıdır', '10² ≡ -1 (mod 11) ilişkisidir'], '10 ≡ -1 (mod 11) olduğu için 10ᵏ ≡ (-1)ᵏ (mod 11) olur; bu da çift ve tek basamak kuvvetlerine sırasıyla artı ve eksi işaret getirir.'),
  ('Rakamları birbirinden farklı dört basamaklı 4a3b sayısı 15 ile tam bölünebildiğine göre a + b toplamının alabileceği en büyük değer kaçtır?', '14', ['15 toplamı', '12 toplamı', '11 toplamı'], '15 = 3·5 olduğundan b = 0 veya b = 5 olabilir. En büyük toplam için b = 5 seçilirse 4 + a + 3 + 5 = 12 + a, 3 ile bölünmeli ve rakamlar farklı olmalı: a ∈ {0, 6, 9}. En büyük a = 9 için a + b = 9 + 5 = 14 bulunur.'),
  ('2ⁿ - 1 biçimindeki bir sayının asal (Mersenne asalı) olabilmesi için n üssü hakkında hangi ifade kesinlikle doğrudur?', 'n sayısı asal olmalıdır', ['n sayısı çift olmalıdır', 'n sayısı 3\'ün katı olmalıdır', 'n tek bileşik sayı olmalıdır'], 'Eğer n = a·b bileşik ise 2ᵃᵇ - 1 ifadesi 2ᵃ - 1 ile tam bölünür; bu nedenle 2ⁿ - 1\'in asal olması için n\'nin asal olması zorunludur.'),
  ('Bir doğal sayının pozitif tam sayı bölenlerinin sayısının tek bir sayı olabilmesi için o sayı hangi özelliğe sahip olmalıdır?', 'Tam kare sayı olmalıdır', ['Asal sayı olmalıdır', 'Tek bir doğal sayı olmalıdır', 'İkinin kuvveti olmalıdır'], 'n = p₁ᵃ¹ · p₂ᵃ² ... için bölen sayısı (a₁+1)(a₂+1)... çarpımının tek olması her aᵢ üssünün çift olmasını, yani sayının tam kare olmasını gerektirir.'),
  ('EBOB(a, b) = 12 ve EKOK(a, b) = 180 olduğuna göre a · b çarpımı kaçtır?', '2160', ['1920 çarpımı', '2400 çarpımı', '1800 çarpımı'], 'Herhangi iki pozitif tam sayı için a · b = EBOB(a, b) · EKOK(a, b) olduğundan a · b = 12 · 180 = 2160 olur.'),
  ('4x ≡ 2 (mod 6) lineer denkliğini sağlayan mod 6\'daki tüm x tam sayı sınıfları hangileridir?', 'x ≡ 2 veya x ≡ 5 (mod 6)', ['Yalnızca x ≡ 2 (mod 6) sınıfı', 'x ≡ 1 veya x ≡ 4 (mod 6)', 'Bu denkliğin hiçbir çözümü yoktur'], 'Denklik 2x ≡ 1 (mod 3) biçimine sadeleşir ve x ≡ 2 (mod 3) bulunur; mod 6\'da bu koşul x ≡ 2 ve x ≡ 5 sınıflarına karşılık gelir.'),
  ('Çin Kalan Teoremi\'ne göre x ≡ a (mod m) ve x ≡ b (mod n) sisteminin mod (m·n) içinde tek bir çözümü olması için m ve n hangi koşulu sağlamalıdır?', 'EBOB(m, n) = 1 olmalıdır', ['m ve n ikisi de asal olmalıdır', 'm sayısı n sayısını tam bölmelidir', 'm + n toplamı tek sayı olmalıdır'], 'Çin Kalan Teoremi, modüllerin ikişer ikişer aralarında asal (EBOB(m, n) = 1) olması durumunda çarpım modülünde benzersiz çözüm garanti eder.'),
  ('4 ile bölündüğünde 1, 5 ile bölündüğünde 2 kalanını veren en küçük pozitif tam sayı kaçtır?', '17', ['13 doğal sayısı', '21 doğal sayısı', '22 doğal sayısı'], '5k + 2 sayıları 2, 7, 12, 17, ... olup 17 ≡ 1 (mod 4) koşulunu sağlayan en küçük pozitif tam sayıdır.'),
  ('Bir okulda iki zil sırasıyla 18 ve 24 dakikada bir çalmaktadır. İlk kez saat 08:30\'da birlikte çaldıklarına göre bir sonraki birlikte çalma saatleri kaçtır?', '09:42', ['09:36 saatinde', '09:54 saatinde', '10:02 saatinde'], 'EKOK(18, 24) = 72 dakika = 1 saat 12 dakika olduğundan 08:30 + 01:12 = 09:42\'de tekrar birlikte çalarlar.'),
  ('Bir a tam sayısının mod m aritmetiğinde çarpmaya göre tersinin bulunabilmesi için hangi koşul sağlanmalıdır?', 'EBOB(a, m) = 1 olmalıdır', ['a sayısı m\'den küçük asal olmalıdır', 'm sayısı çift bir doğal sayı olmalıdır', 'a sayısı m\'nin tam böleni olmalıdır'], 'ax ≡ 1 (mod m) denkliğinin çözülebilir olması için a ve m aralarında asal, yani EBOB(a, m) = 1 olmalıdır.'),
  ('Üç basamaklı en küçük asal sayı kaçtır?', '101', ['103 doğal sayısı', '107 doğal sayısı', '109 doğal sayısı'], '100 bileşiktir; 101 sayısı √101 < 11 olduğundan 2, 3, 5, 7 asal sayılarının hiçbirine bölünmez ve en küçük üç basamaklı asaldır.'),
  ('İkilik tabanda verilen 110101₂ - 10110₂ çıkarma işleminin sonucu ikilik tabanda hangisidir?', '11111₂', ['10111 ikilik tabanda', '100111 ikilik tabanda', '11011 ikilik tabanda'], '110101₂ = 53 ve 10110₂ = 22 olduğundan fark 53 - 22 = 31 = 2⁵ - 1 = 11111₂ olarak bulunur.'),
  ('Bir doğal sayı 3 tabanında 4 basamaklı olarak yazılabiliyorsa onluk tabanda alabileceği en büyük değer kaçtır?', '80', ['81 doğal sayısı', '79 doğal sayısı', '26 doğal sayısı'], 'Üçlük tabandaki en büyük 4 basamaklı sayı (2222)₃ = 3⁴ - 1 = 81 - 1 = 80\'dir.'),
  ('Bir öğrenci 1013 sayısının asal olup olmadığını test etmek için 2\'den 31\'e kadar tüm asal sayılara bölünebilirliğini kontrol etmiş ve hiçbiriyle tam bölünmediğini görmüştür. Öğrencinin vardığı sonuç neden yeterlidir?', '√1013 < 32 olduğundan daha büyük asal testine gerek yoktur', ['1013 sayısı 4k + 1 biçiminde olduğu için kesin asaldır', '31\'den büyük asal sayılar dört basamaklı sayıları bölemez', 'Bir sayının asal olması için ilk 10 asala bölünmemesi yeterlidir'], '32² = 1024 > 1013 olduğundan 1013 bileşik olsaydı en az bir asal çarpanı 32\'den küçük (en çok 31) olmak zorundaydı; bölünmediği için kesinlikle asaldır.'),
  ('70 kuralına göre 20 yılda ikiye katlandığı gözlemlenen bir şehrin nüfusunun yıllık ortalama büyüme oranı yaklaşık yüzde kaçtır?', '3,5', ['4,5 yüzde oranı', '2,5 yüzde oranı', '5,0 yüzde oranı'], 't ≈ 70 / r ⇒ r ≈ 70 / 20 = 3,5 olduğundan yıllık büyüme oranı yaklaşık %3,5\'tir.'),
  ('70 kuralında pay olarak 70 (bazen 69,3 veya 72) sayısının seçilmesinin matematiksel kaynağı hangi logaritmik sabittir?', '100 · ln(2)', ['100 · log₁₀(2) değeri', '100 · ln(e) değeri', '100 · log₂(10) değeri'], 'e^(rt) = 2 denkleminden t = ln(2) / r elde edilir; r yüzde cinsinden (r/100) yazıldığında t = 100·ln(2) / r ≈ 69,3 / r ≈ 70 / r olur.'),
  ('Bir popülasyon P(t) = P₀ · e^(0,04t) sürekli büyüme modeline uymaktadır. ln(2) ≈ 0,693 alındığında ikiye katlanma süresi kaç zaman birimidir?', '17,325', ['15,625 zaman birimi', '21,450 zaman birimi', '13,860 zaman birimi'], '2P₀ = P₀ · e^(0,04t) ⇒ 0,04t = ln(2) ≈ 0,693 ⇒ t = 0,693 / 0,04 = 17,325 bulunur.'),
  ('Doğada sınırlı kaynaklara sahip bir ekosistemde popülasyonun önce hızlı artıp sonra taşıma kapasitesine (K) yaklaşarak yataylaştığı büyüme modeli hangisidir?', 'Lojistik büyüme', ['Doğrusal büyüme modeli', 'Sınırsız üstel büyüme', 'Harmonik salınım modeli'], 'Lojistik büyüme (S-eğrisi), başlangıçta üstele yakın büyürken kaynak kısıtı nedeniyle büyüme hızının azalıp K taşıma kapasitesine yakınsamasını betimler.'),
  ('Lojistik büyüme denklemi P(t) = K / (1 + A · e^(-rt)) (K, A, r > 0) biçiminde verildiğinde t sonsuza giderken popülasyon hangi değere yaklaşır?', 'K', ['K / (1 + A) değerine', 'A · K çarpımına', 'Sıfır değerine'], 't → ∞ iken e^(-rt) → 0 olduğundan payda 1\'e yaklaşır ve P(t) → K / 1 = K (taşıma kapasitesi) elde edilir.'),
  ('Bir lojistik büyüme eğrisinde (S-eğrisi) popülasyonun anlık artış hızı (dP/dt), nüfus P hangi değere ulaştığında maksimum olur?', 'K / 2', ['K değerine ulaştığında', 'K / 4 değerine ulaştığında', 'K / e değerine ulaştığında'], 'Lojistik diferansiyel denklem dP/dt = rP(1 - P/K) parabolik bir ifadedir ve tepe noktası olan P = K/2 değerinde maksimum hızına ulaşır.'),
  ('Sınırsız üstel büyüme modeli P(t) = P₀ · e^(rt) yerine gerçek ekosistemlerde lojistik modelin tercih edilmesinin temel nedeni nedir?', 'Çevresel direnç ve kaynak sınırını yansıtması', ['Matematiksel hesaplamasının daha kısa sürmesi', 'Yalnızca tek hücreli canlılarda geçerli olması', 'Başlangıç popülasyonunu sıfır kabul edebilmesi'], 'Gerçek doğada besin, alan ve avcı baskısı gibi çevresel direnç faktörleri sonsuz büyümeyi engeller; lojistik model bu taşıma kapasitesi sınırını içerir.'),
  ('f(x) = aˣ üstel fonksiyonu ile g(x) = logₐ(x) logaritma fonksiyonunun grafikleri koordinat düzleminde hangi doğruya göre birbirinin simetriğidir?', 'y = x', ['y = -x doğrusuna göre', 'y = 0 (x ekseni) doğrusuna', 'x = 0 (y ekseni) doğrusuna'], 'Ters fonksiyonların grafikleri analitik düzlemde y = x birinci açıortay doğrusuna göre simetriktir.'),
  ('log₁₀(x) + log₁₀(x - 3) = 1 denkleminin gerçek sayılardaki çözüm kümesi hangisidir?', '{5}', ['{-2, 5} kümesi', '{2, 5} kümesi', '{10} kümesi'], 'log₁₀(x(x - 3)) = 1 ⇒ x² - 3x = 10 ⇒ (x - 5)(x + 2) = 0 olur. Tanım kümesi x > 3 gerektirdiğinden x = -2 elenir ve tek kök 5\'tir.'),
  ('Bir konser salonunda ses düzeyi 70 dB\'den 100 dB\'ye yükseldiğinde ses şiddeti (I) kaç katına çıkmıştır?', '1000', ['30 katına çıkmıştır', '300 katına çıkmıştır', '100 katına çıkmıştır'], '100 - 70 = 30 = 10 · log₁₀(I₂ / I₁) ⇒ log₁₀(I₂ / I₁) = 3 ⇒ I₂ / I₁ = 10³ = 1000 katına çıkmıştır.'),
  ('log₁₀(2) ≈ 0,301 ve log₁₀(3) ≈ 0,477 verildiğinde log₁₀(72) değerinin yaklaşık karşılığı nedir?', '1,857', ['1,757 değeri', '1,957 değeri', '1,556 değeri'], '72 = 2³ · 3² olduğundan log₁₀(72) = 3·log₁₀(2) + 2·log₁₀(3) ≈ 3(0,301) + 2(0,477) = 0,903 + 0,954 = 1,857 elde edilir.'),
  ('log₁₀(2) ≈ 0,301 bilindiğine göre log₁₀(5) değerinin yaklaşık sonucu kaçtır?', '0,699', ['0,701 değeri', '0,602 değeri', '0,599 değeri'], 'log₁₀(5) = log₁₀(10 / 2) = 1 - log₁₀(2) ≈ 1 - 0,301 = 0,699 olur.'),
  ('T(t) = 22 + 70 · e^(-0,1t) soğuma modelinde 22 sabit sayısı fiziksel olarak neyi temsil eder?', 'Ortamın (çevrenin) sıcaklığını', ['Cismin başlangıç sıcaklığını', 'Cismin soğuma hızı sabitini', 'İlk dakikadaki sıcaklık düşüşünü'], 't → ∞ iken e^(-0,1t) → 0 ve T(t) → 22 olduğundan 22 °C cismin ısıl dengeye ulaşacağı ortam sıcaklığıdır.'),
  ('Yıllık %10 bileşik faizle bankaya yatırılan A lira, t yıl sonunda A · (1,1)ᵗ liraya ulaşır. Paranın 2 katına çıkması için gereken t yıl sayısı logaritma cinsinden hangisidir?', 'log_(1,1)(2)', ['log₂(1,1) değeri', 'ln(2) / 1,1 değeri', '2 · log₁₀(1,1) değeri'], 'A · (1,1)ᵗ = 2A ⇒ (1,1)ᵗ = 2 ⇒ t = log_(1,1)(2) olarak bulunur.'),
  ('Sürekli bileşik faiz formülü A(t) = P · e^(rt) ile yıllık bir kez bileşiklenen A(t) = P · (1 + r)ᵗ karşılaştırıldığında aynı P, r > 0 ve t > 0 için hangisi her zaman daha büyük değer verir?', 'Sürekli bileşik faiz', ['Yıllık tek bileşik faiz', 'İkisi de her t için eşittir', 'r > 1 olduğunda yıllık faiz'], 'Her r > 0 için eʳ > 1 + r eşitsizliği sağlandığından sürekli bileşik faiz P·e^(rt) daima daha büyük tutar üretir.'),
  ('Bir bakteri kolonisi saatlik %20 artışla büyümektedir. Başlangıçta 500 bakteri varsa 2 saat sonra kaç bakteri olur?', '720', ['700 bakteri sayısı', '620 bakteri sayısı', '750 bakteri sayısı'], 'P(2) = 500 · (1,2)² = 500 · 1,44 = 720 bakteri olur.'),
  ('Bir ilacın kandaki miktarı her 4 saatte bir %50 azalmaktadır. Hastaya 320 mg ilaç verildikten 12 saat sonra kanda kaç mg ilaç kalır?', '40', ['80 mg ilaç miktarı', '20 mg ilaç miktarı', '60 mg ilaç miktarı'], '12 / 4 = 3 yarılanma gerçekleşir: 320 · (0,5)³ = 320 / 8 = 40 mg kalır.'),
  ('Değeri her yıl %20 oranında amortismanla azalan 50.000 TL\'lik bir makinenin 2 yıl sonraki değeri kaç TL olur?', '32.000', ['30.000 TL değerinde', '36.000 TL değerinde', '40.000 TL değerinde'], 'Her yıl değer 0,8 katına iner: 50.000 · (0,8)² = 50.000 · 0,64 = 32.000 TL olur.'),
  ('f(x) = 2^(x - 1) + 3 fonksiyonunun tersi olan f⁻¹(x) fonksiyonu aşağıdakilerden hangisidir?', 'log₂(x - 3) + 1', ['log₂(x + 3) - 1 fonksiyonu', 'log₂(x - 1) + 3 fonksiyonu', 'log₃(x - 2) + 1 fonksiyonu'], 'y = 2^(x-1) + 3 ⇒ y - 3 = 2^(x-1) ⇒ log₂(y - 3) = x - 1 ⇒ x = log₂(y - 3) + 1, yani f⁻¹(x) = log₂(x - 3) + 1 olur.'),
  ('Bir virüsün günlük bulaşma katsayısı R = 1,5 olup her nesil 4 gün sürmektedir. Başlangıçta 16 kişi enfekte ise 3 nesil (12 gün) sonunda enfekte kişi sayısı kaç olur?', '54', ['48 kişi sayısı', '72 kişi sayısı', '36 kişi sayısı'], 'N = 16 · (1,5)³ = 16 · (3/2)³ = 16 · (27/8) = 2 · 27 = 54 kişi bulunur.'),
  ('Aynı başlangıç değerinden (P₀ = 10) başlayan doğrusal f(t) = 10 + 50t ve üstel g(t) = 10 · 2ᵗ modelleri karşılaştırıldığında hangi ifade doğrudur?', 'Yeterince büyük t için g(t) her zaman f(t)\'yi geçer', ['Doğrusal fonksiyonun eğimi büyük olduğundan f(t) daima öndedir', 'İki fonksiyon yalnızca t = 0 noktasında kesişir', 't = 5 anında üstel fonksiyon hâlâ doğrusaldan küçüktür'], 'Başlangıçta f(t) önde olsa da (t=5 için f(5)=260, g(5)=320 > 260) üstel büyüme her doğrusal fonksiyonu sonlu bir sürede aşar ve hızla öne geçer.'),
  ('Bir finansal varlık ilk yıl %25 değer kazanıp ikinci yıl %20 değer kaybederse, iki yılın sonundaki toplam değişim yüzdesi ne olur?', '%0', ['%5 net artış olur', '%5 net azalış olur', '%2 net artış olur'], 'Başlangıç 100 iken 1. yıl 100 · 1,25 = 125; 2. yıl 125 · 0,80 = 100 olur; iki yıl sonunda net değişim %0\'dır.'),
  ('e^(2x) - 5eˣ + 6 = 0 denklemini sağlayan x değerlerinin toplamı aşağıdakilerden hangisidir?', 'ln(6)', ['ln(5) toplamı', 'ln(2) toplamı', 'ln(3) toplamı'], 'u = eˣ için u² - 5u + 6 = 0 ⇒ u₁ = 2, u₂ = 3 ⇒ x₁ = ln(2), x₂ = ln(3). Toplam ln(2) + ln(3) = ln(6) bulunur.'),
];
